pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    function testFuzz_property(address from, address to1, address to2, uint256 v1, uint256 v2) public {
        vm.assume(to1 != address(0) || to2 != address(0));

        ReverterThenSucceeder helper = new ReverterThenSucceeder();

        address[] memory tos = new address[](2);
        tos[0] = address(helper);
        tos[1] = address(helper);
        uint[] memory vals = new uint[](2);
        vals[0] = v1;
        vals[1] = v2;

        bool ok;
        try c.transfer(from, address(helper), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract ReverterThenSucceeder {
    bool public first = true;
    fallback() external payable {
        if (first) {
            first = false;
            revert("forced revert");
        }
    }
}
